'use strict';
function desktopNavigation(){return `<a class="desktop-nav-brand" href="#today"><span>✦</span>KainCheck<small>WELLNESS, YOUR WAY</small></a>`;}
function desktopNavigationFooter(){return `<div class="desktop-nav-footer"><span class="desktop-plan">${tier()}</span><button data-action="profile"><span class="desktop-user-avatar">${userAvatar()}</span><span><strong>${esc(state.name)}</strong><small>Your personal space</small></span>${ic('arrow')}</button></div>`;}
function wrapResponsivePanels(page,start,split,kind){if(!start)return;const grid=document.createElement('div');grid.className='responsive-panels '+kind;const main=document.createElement('div'),side=document.createElement('div');main.className='responsive-main';side.className='responsive-side';page.insertBefore(grid,start);let node=start,inSide=false;while(node){const next=node.nextSibling;if(node===split)inSide=true;(inSide?side:main).append(node);node=next;}grid.append(main,side);}
function prepareResponsiveScreen(){const app=$('#app');app.dataset.screen=screen;const page=app.querySelector('.screen');if(page){page.classList.add('screen-'+screen);if(screen==='today')wrapResponsivePanels(page,page.querySelector('.today-hero'),page.querySelector('.section-top'),'dashboard-panels');if(screen==='food')wrapResponsivePanels(page,page.querySelector('#food-list'),page.querySelector('#food-list')?.nextElementSibling,'food-panels');if(screen==='progress')wrapResponsivePanels(page,page.querySelector('.progress-hero'),page.querySelector('.progress-grid'),'progress-panels');if(screen==='profile')wrapResponsivePanels(page,page.querySelector('.profile-head'),page.querySelector('.settings-row'),'profile-panels');}
 if(screen==='coach'){const section=app.querySelector('.coach-screen'),aside=document.createElement('aside');aside.className='desktop-coach-context';aside.innerHTML=`<p class="desktop-overline">YOUR DAILY COMPANION</p><span class="desktop-coach-avatar">${coachAvatar()}</span><h2>${esc(state.coach.name)}</h2><p>${state.coachType==='custom'?'Your character. Your way to connect.':'A little support for your everyday.'}</p><button class="secondary" data-action="customize">${ic('settings')}Customize coach</button><button class="text-btn" data-action="coach-library">Browse coaches</button><div class="desktop-context-card"><small>YOUR DAY AT A GLANCE</small><b>₱${esc(state.budget)} <span>food budget</span></b><b>${esc(state.time)} min <span>for movement</span></b><p>${esc(state.goal)}</p></div><button class="desktop-context-link" data-action="food-checker">${ic('food')}Check a dish photo ${ic('arrow')}</button>`;section.prepend(aside);}
}
